namespace Microsoft.Xna.Framework { public record struct Vector2(float X,float Y) {public static Vector2 Zero=>new(0,0);public static float DistanceSquared(Vector2 a,Vector2 b){var d=a-b;return d.X*d.X+d.Y*d.Y;}public float Length()=>MathF.Sqrt(X*X+Y*Y);public float ToRotation()=>MathF.Atan2(Y,X);public static Vector2 operator -(Vector2 a,Vector2 b)=>new(a.X-b.X,a.Y-b.Y);public static Vector2 operator /(Vector2 a,float b)=>new(a.X/b,a.Y/b);public static Vector2 operator *(Vector2 a,float b)=>new(a.X*b,a.Y*b);} }
namespace Terraria { public class NPC {public bool active;public Terraria.ModLoader.ModNPC ModNPC;public int type,whoAmI,realLife=-1,life,lifeMax,damage,defense,timeLeft,target;public bool netUpdate;public float[] ai=new float[4];public float rotation;public Microsoft.Xna.Framework.Vector2 Center,velocity;public object GetSource_FromAI()=>null;public static int Calls,FailAt;public static int NewNPC(object source,int x,int y,int type,float ai0,float ai1,float ai2){Calls++;if(Calls==FailAt)return Main.maxNPCs;for(int i=0;i<Main.maxNPCs;i++)if(!Main.npc[i].active){var n=new NPC{whoAmI=i,active=true,type=type,life=70,lifeMax=70};Main.npc[i]=n;n.ModNPC=new XianXia.Content.NPCs.Bosses.TestSegment();n.ModNPC.NPC=n;n.ai[0]=ai0;n.ai[1]=ai1;n.ai[2]=ai2;return i;}return Main.maxNPCs;}} public static class Main {public static int maxNPCs=8,netMode,maxPlayers=2;public static Player[] player=[new(),new()];public static bool dedServ;public static NPC[] npc=Array.Empty<NPC>();} public static class Lighting {public static int Calls;public static void AddLight(Microsoft.Xna.Framework.Vector2 p,float r,float g,float b)=>Calls++;} public static class NetMessage {public static int Calls;public static void SendData(int id,int number)=>Calls++;} }
